class t{static formatDateTime(t){const a=new Date(t);return`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,"0")}-${String(a.getDate()).padStart(2,"0")} ${String(a.getHours()).padStart(2,"0")}:${String(a.getMinutes()).padStart(2,"0")}:${String(a.getSeconds()).padStart(2,"0")}`}static formatDuration(t){const a=Math.floor(t/3600),r=Math.floor(t%3600/60),e=Math.floor(t%60);return`${String(a).padStart(2,"0")}:${String(r).padStart(2,"0")}:${String(e).padStart(2,"0")}`}}export{t as D};
